// boot-server.js -- GENERATED by effortless-rulebook-editor.
//
// Binds the EXTERNAL UI port (5174) immediately at container start, before
// Postgres/build even begin. Serves a placeholder boot page with a live
// SSE log tail + progress state, a "Rebuild" trigger, and once the real
// Vite dev server is confirmed reachable on the INTERNAL port (5175),
// transparently reverse-proxies everything else to it. The external port
// never changes, so a browser tab opened at t=0 just starts working once
// the build finishes -- no manual reload-until-it-works.
//
// State transitions (read from BOOT_STATE_FILE, written by
// container-entrypoint.sh): booting -> building -> ready | error

const http = require('http');
const fs = require('fs');

const EXTERNAL_PORT = 5174;
const INTERNAL_UI_PORT = 5175;
const STATE_FILE = process.env.BOOT_STATE_FILE || '/tmp/boot-state';
const LOG_FILE = process.env.BOOT_LOG_FILE || '/tmp/current-build.log';
const REBUILD_TRIGGER = process.env.BOOT_REBUILD_TRIGGER || '/tmp/rebuild-trigger';

function readState() {
  try {
    return fs.readFileSync(STATE_FILE, 'utf8').trim() || 'booting';
  } catch {
    return 'booting';
  }
}

function tailLines(n) {
  try {
    const data = fs.readFileSync(LOG_FILE, 'utf8');
    const lines = data.split('\n');
    return lines.slice(Math.max(0, lines.length - n));
  } catch {
    return [];
  }
}

const sseClients = new Set();

function broadcastLine(line) {
  for (const res of sseClients) {
    res.write(`data: ${JSON.stringify({ line })}\n\n`);
  }
}

function broadcastState(state) {
  for (const res of sseClients) {
    res.write(`event: state\ndata: ${JSON.stringify({ state })}\n\n`);
  }
}

// Watch the log file for new lines (tail -f semantics via fs.watchFile --
// portable, no extra deps, adequate for a single-writer append-only log).
let lastSize = 0;
try { lastSize = fs.existsSync(LOG_FILE) ? fs.statSync(LOG_FILE).size : 0; } catch {}
fs.watchFile(LOG_FILE, { interval: 300 }, () => {
  try {
    const stat = fs.statSync(LOG_FILE);
    if (stat.size < lastSize) lastSize = 0; // log truncated at the start of a rebuild
    const fd = fs.openSync(LOG_FILE, 'r');
    const len = stat.size - lastSize;
    if (len > 0) {
      const buf = Buffer.alloc(len);
      fs.readSync(fd, buf, 0, len, lastSize);
      buf.toString('utf8').split('\n').filter(Boolean).forEach(broadcastLine);
      lastSize = stat.size;
    }
    fs.closeSync(fd);
  } catch {}
});

let lastState = '';
setInterval(() => {
  const s = readState();
  if (s !== lastState) {
    lastState = s;
    broadcastState(s);
  }
}, 500);

const BOOT_PAGE = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Rulebook Editor -- booting</title>
<style>
  :root{color-scheme:light dark}
  body{margin:0;font-family:ui-monospace,SF Mono,Menlo,Cascadia Code,monospace;
    background:#0d1315;color:#d3dcd9;height:100vh;display:flex;flex-direction:column}
  @media (prefers-color-scheme:light){body{background:#f5f7f6;color:#1a2320}}
  header{padding:16px 22px;border-bottom:1px solid #233033;display:flex;align-items:center;gap:12px}
  @media (prefers-color-scheme:light){header{border-bottom-color:#d8dfdd}}
  h1{font-size:15px;margin:0;font-weight:650}
  .dot{width:9px;height:9px;border-radius:50%;background:#e0a03a;animation:pulse 1.4s ease-in-out infinite}
  .dot.ready{background:#4ea882;animation:none}
  .dot.error{background:#e05a3a;animation:none}
  @keyframes pulse{0%,100%{opacity:.35}50%{opacity:1}}
  .state{font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:#93a29d}
  .spacer{flex:1}
  button{font-family:inherit;font-size:12px;background:#141b1e;color:#d3dcd9;
    border:1px solid #233033;border-radius:6px;padding:7px 14px;cursor:pointer}
  @media (prefers-color-scheme:light){button{background:#eef2f1;color:#1a2320;border-color:#d8dfdd}}
  button:hover{filter:brightness(1.15)}
  button:disabled{opacity:.5;cursor:default}
  main{flex:1;overflow-y:auto;padding:14px 22px;font-size:12.5px;line-height:1.6;white-space:pre-wrap}
  .hint{padding:10px 22px;font-size:12px;color:#93a29d;border-top:1px solid #233033}
  @media (prefers-color-scheme:light){.hint{border-top-color:#d8dfdd}}
</style>
</head>
<body>
<header>
  <span class="dot" id="dot"></span>
  <h1>effortless-rulebook-editor</h1>
  <span class="state" id="stateLabel">booting</span>
  <div class="spacer"></div>
  <button id="rebuildBtn">Rebuild</button>
</header>
<main id="log"></main>
<div class="hint" id="hint">Waiting for the container to finish its first build. This page auto-refreshes into the app once it's ready.</div>
<script>
  const logEl = document.getElementById('log');
  const dot = document.getElementById('dot');
  const stateLabel = document.getElementById('stateLabel');
  const hint = document.getElementById('hint');
  const rebuildBtn = document.getElementById('rebuildBtn');

  function appendLine(line) {
    logEl.textContent += line + "\n";
    logEl.scrollTop = logEl.scrollHeight;
  }

  function setState(state) {
    stateLabel.textContent = state;
    dot.className = 'dot' + (state === 'ready' ? ' ready' : state === 'error' ? ' error' : '');
    if (state === 'ready') {
      hint.textContent = 'Build finished -- loading the app...';
      setTimeout(() => window.location.reload(), 600);
    } else if (state === 'error') {
      hint.textContent = 'Build failed -- see log above. Fix the rulebook and save, or click Rebuild.';
    } else {
      hint.textContent = 'Waiting for the container to finish its build. This page auto-refreshes into the app once ready.';
    }
  }

  fetch('/__boot/log').then(r => r.json()).then(({ lines, state }) => {
    lines.forEach(appendLine);
    setState(state);
  });

  const es = new EventSource('/__boot/events');
  es.onmessage = (e) => appendLine(JSON.parse(e.data).line);
  es.addEventListener('state', (e) => setState(JSON.parse(e.data).state));

  rebuildBtn.onclick = () => {
    rebuildBtn.disabled = true;
    fetch('/__boot/rebuild', { method: 'POST' }).finally(() => {
      setTimeout(() => { rebuildBtn.disabled = false; }, 3000);
    });
  };
</script>
</body>
</html>
`;

function proxyToInternalUI(req, res) {
  const proxyReq = http.request(
    {
      host: '127.0.0.1',
      port: INTERNAL_UI_PORT,
      path: req.url,
      method: req.method,
      headers: req.headers,
    },
    (proxyRes) => {
      res.writeHead(proxyRes.statusCode, proxyRes.headers);
      proxyRes.pipe(res);
    },
  );
  proxyReq.on('error', () => {
    res.writeHead(502, { 'content-type': 'text/plain' });
    res.end('rulebook-editor: internal UI not reachable yet');
  });
  req.pipe(proxyReq);
}

// Static output from the three "document" transpilers (RuleSpeak EN/DE,
// XLSX export) -- these are plain files dropped by `effortless build` into
// fixed container directories (see effortless.editor.json's RelativePath for
// each), not apps with their own server. Whitelisted prefix -> directory map
// only (no arbitrary path passthrough), and each request is re-resolved
// against the real directory + guarded against `..` escape before any read.
const STATIC_TOOL_DIRS = {
  '/__tools/rulespeak': '/app/rulespeak',
  '/__tools/rulespeak-de': '/app/rulespeak-de',
  '/__tools/xlsx': '/app/xlsx',
};
const path = require('path');

function serveStaticTool(req, res, urlPrefix, rootDir) {
  const rel = decodeURIComponent(req.url.slice(urlPrefix.length));

  // A bare directory request (no filename) resolves to whatever single file
  // is actually in that directory, rather than a hardcoded name -- e.g.
  // rulebook-to-xlsx names its output after the (slugified) rulebook, not a
  // fixed "rulebook.xlsx", so the portal can link to "/__tools/xlsx/"
  // without needing to know that slug.
  if (!rel || rel === '/') {
    let entries;
    try {
      entries = fs.readdirSync(rootDir).filter((f) => !f.startsWith('.'));
    } catch {
      entries = [];
    }
    if (entries.length === 1) {
      serveFile(res, path.join(rootDir, entries[0]));
      return;
    }
    if (entries.includes('index.html')) {
      serveFile(res, path.join(rootDir, 'index.html'));
      return;
    }
    res.writeHead(404, { 'content-type': 'text/plain' });
    res.end(`no single file to serve in ${rootDir} (found: ${entries.join(', ') || 'nothing -- has the build run yet? see /__boot/log'})`);
    return;
  }

  const target = path.normalize(path.join(rootDir, rel));
  if (!target.startsWith(path.normalize(rootDir))) {
    res.writeHead(400, { 'content-type': 'text/plain' });
    res.end('bad path');
    return;
  }
  serveFile(res, target);
}

function serveFile(res, target) {
  fs.readFile(target, (err, data) => {
    if (err) {
      res.writeHead(404, { 'content-type': 'text/plain' });
      res.end(`not found: ${rel} (has the build run yet? see /__boot/log)`);
      return;
    }
    const ext = path.extname(target).toLowerCase();
    const contentType =
      ext === '.html' ? 'text/html' :
      ext === '.md' ? 'text/markdown' :
      ext === '.xlsx' ? 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' :
      ext === '.json' ? 'application/json' :
      'application/octet-stream';
    res.writeHead(200, { 'content-type': contentType });
    res.end(data);
  });
}

const server = http.createServer((req, res) => {
  for (const [prefix, dir] of Object.entries(STATIC_TOOL_DIRS)) {
    if (req.url === prefix || req.url.startsWith(prefix + '/')) {
      serveStaticTool(req, res, prefix, dir);
      return;
    }
  }

  if (req.url === '/__boot/log') {
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ lines: tailLines(400), state: readState() }));
    return;
  }
  if (req.url === '/__boot/events') {
    res.writeHead(200, {
      'content-type': 'text/event-stream',
      'cache-control': 'no-cache',
      connection: 'keep-alive',
    });
    res.write(': connected\n\n');
    sseClients.add(res);
    req.on('close', () => sseClients.delete(res));
    return;
  }
  if (req.url === '/__boot/rebuild' && req.method === 'POST') {
    fs.writeFileSync(REBUILD_TRIGGER, String(Date.now()));
    res.writeHead(202, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ triggered: true }));
    return;
  }

  const state = readState();
  if (state === 'ready') {
    proxyToInternalUI(req, res);
    return;
  }

  res.writeHead(200, { 'content-type': 'text/html' });
  res.end(BOOT_PAGE);
});

server.listen(EXTERNAL_PORT, '0.0.0.0', () => {
  console.log(`[boot-server] listening on :${EXTERNAL_PORT} (proxies to internal UI on :${INTERNAL_UI_PORT} once ready)`);
});
